#!/usr/bin/env bash
# ============================================================================
# ZONO 9.8 — PAID ONBOARDING LAUNCH CLOSURE — apply + push
# Run from the repo root (/Users/talzatelman/code/zono-os):
#   bash apply-zono-9-8.sh
# ============================================================================
set -euo pipefail
if [ ! -d .git ]; then echo "ERROR: run this from the zono-os repo root." >&2; exit 1; fi
echo "→ Syncing with origin/main…"
git fetch origin main
git checkout main
git pull --ff-only origin main || true
PATCH="$(mktemp /tmp/zono-9-8.XXXXXX.patch)"
base64 -d > "$PATCH" <<'PATCH_B64'

PATCH_B64
echo "→ Applying 9.8 commit…"
git am --3way "$PATCH" || { echo "git am failed — resolve, then 'git am --continue'." >&2; exit 1; }
echo "→ Pushing to origin/main…"
git push origin main
rm -f "$PATCH"
echo "✓ ZONO 9.8 applied and pushed."
